css:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  height: 100vh;
  background: linear-gradient(to bottom, #000 0%, #999 100%);
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
}

input {
  -webkit-appearance: none;
  appearance: none;
  margin: 10px;
  width: 24px;
  height: 24px;
  border-radius: 12px;
  cursor: pointer;
  box-shadow: rgba(255, 255, 255, 0.15) 0 1px 1px, inset rgba(0, 0, 0, 0.5);
  background-color: rgba(0, 0, 0, 0.2);
  background-image: radial-gradient(
    rgb(204, 238, 255) 0%,
    rgb(102, 204, 255) 15%,
    rgba(51, 187, 255, 0.302) 28%,
    rgba(0, 102, 153, 0) 70%
  );
  background-repeat: no-repeat;
  transition: background-position 0.15s ease-in;
  outline: none;
}

input:checked {
  transition: 0.2s 0.15s ease-in-out;
}

input:active {
  transform: scale(1.5);
}

input,
input:active {
  background-position: 0 24px;
}

input:checked {
  background-position: 0 0;
}

input:checked ~ input,
input:checked ~ input:active {
  background-position: 0 -24px;
}

h1 {
  position: absolute;
  top: 140px;
  color: white;
  font-family: cursive;
  text-align: center;
  margin: 0 250px;
}
